document.addEventListener('DOMContentLoaded', () => {
    const carousels = document.querySelectorAll('.home-categories');

    carousels.forEach((carousel) => {
        const track = carousel.querySelector('.home-categories__track');
        const previous = carousel.querySelector('.home-categories__prev');
        const next = carousel.querySelector('.home-categories__next');

        if (!track || !previous || !next) {
            return;
        }

        const getScrollAmount = () => {
            const slide = track.querySelector('.home-categories__slide');

            if (!slide) {
                return 0;
            }

            const gap = parseFloat(window.getComputedStyle(track).columnGap) || 0;

            return slide.getBoundingClientRect().width + gap;
        };

        const updateButtons = () => {
            const maxScroll = track.scrollWidth - track.clientWidth;

            previous.disabled = track.scrollLeft <= 1;
            next.disabled = track.scrollLeft >= maxScroll - 1;
        };

        previous.addEventListener('click', () => {
            track.scrollBy({
                left: -getScrollAmount(), behavior: 'smooth',
            });
        });

        next.addEventListener('click', () => {
            track.scrollBy({
                left: getScrollAmount(), behavior: 'smooth',
            });
        });

        track.addEventListener('scroll', updateButtons, {
            passive: true,
        });

        window.addEventListener('resize', updateButtons);

        updateButtons();
    });
});